/**
 * Returns all simulation transactions that have occurred up to the current clock time.
 * Future transactions (scheduled for later today or upcoming days) remain hidden until
 * real clock time reaches their timestamp, allowing live real-time demonstrations!
 */
export function getVisibleSeedTransactions() {
  const now = new Date();
  return SEED_TRANSACTIONS.filter((t) => new Date(t.created_at) <= now);
}

export function getVisibleReviews() {
  const now = new Date();
  return SEED_REVIEWS.filter((r) => new Date(r.created_at) <= now);
}
